'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const MOODS=[{id:'happy',label:'开心',face:'◡',color:'#f7d797',words:'这一刻的小快乐，值得好好收藏。'},{id:'calm',label:'平静',face:'⌣',color:'#ebd4ba',words:'什么都不用赶，安静待一会儿也很好。'},{id:'sad',label:'低落',face:'︵',color:'#d8d4e5',words:'今天有点难过也没关系，我在这里陪你。'},{id:'anxious',label:'焦虑',face:'﹏',color:'#edc6b9',words:'不用一次想明白所有事。我们先做眼前一小步。'},{id:'angry',label:'生气',face:'︿',color:'#eaa99c',words:'生气也可以被听见。先给自己留一点空间。'},{id:'tired',label:'疲惫',face:'−',color:'#d7c7bb',words:'累了就靠一会儿，休息也值得认真对待。'}];
const TAGS=['学业','人际','竞赛','生活','身体','自己'];
const KEY='naiwa-mood-v1';let records=[],demo=false,demoRecords=[],selectedMood='',selectedTags=new Set(),editing=null,selectedDay='',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),pendingDelete=null,storageAvailable=true,restTimer=null,restEnd=0;
const mood=id=>MOODS.find(x=>x.id===id)||MOODS[1];
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const activeRecords=()=>demo?demoRecords:records;
const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
let toastTimer,bubbleTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function face(m){const e=make('span','face',m.face);e.style.setProperty('--face',m.color);e.setAttribute('aria-hidden','true');return e}
function validateRecord(r){return r&&typeof r.id==='string'&&MOODS.some(m=>m.id===r.mood)&&typeof r.note==='string'&&r.note.length<=1500&&Array.isArray(r.tags)&&r.tags.every(t=>TAGS.includes(t))&&Number.isInteger(r.intensity)&&r.intensity>=1&&r.intensity<=5&&typeof r.created==='string'&&Number.isFinite(Date.parse(r.created))}
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(validateRecord))throw Error('invalid');records=data}localStorage.setItem('naiwa-storage-test','1');localStorage.removeItem('naiwa-storage-test')}catch(e){storageAvailable=false;setTimeout(()=>toast('当前无法读取或保存记录。请保留此页面，检查浏览器存储设置。'),700);$('#saveHint').textContent='本地存储不可用，暂时无法保存';$('#saveBtn').disabled=true}
function persist(next){if(demo){demoRecords=next;return true}try{localStorage.setItem(KEY,JSON.stringify(next));records=next;return true}catch(e){toast('没有保存成功，可能是存储空间不足。文字还在，请先复制留存。');return false}}
$('#todayDate').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
MOODS.forEach(m=>{const b=make('button','mood');b.type='button';b.dataset.mood=m.id;b.setAttribute('aria-pressed','false');b.append(face(m),make('span','',m.label));b.addEventListener('click',()=>selectMood(m.id));$('#moodPicker').append(b);const o=make('option','',m.label);o.value=m.id;$('#filterMood').append(o)});
TAGS.forEach(t=>{const b=make('button','tag',t);b.type='button';b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{selectedTags.has(t)?selectedTags.delete(t):selectedTags.add(t);syncTags()});$('#tagPicker').append(b)});
function syncTags(){$$('#tagPicker button').forEach(b=>{const on=selectedTags.has(b.textContent);b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))})}
function selectMood(id){selectedMood=id;$$('.mood').forEach(b=>{const on=b.dataset.mood===id;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});if(id){$('#kindWords').textContent=mood(id).words;showCompanion(id)}}
$('#intensity').addEventListener('input',()=>$('#intensityValue').textContent=`${$('#intensity').value} / 5`);
$('#note').addEventListener('input',()=>$('#wordCount').textContent=`${$('#note').value.length} / 1500`);
const prompts=['此刻，我最想被理解的一件事是……','今天有哪个小瞬间，让我停了一下？','如果对自己温柔一点，我想说……','让我有这种感受的事情是……','我现在最需要的，可能是……'];let promptIndex=0;
$('#promptBtn').addEventListener('click',()=>{const t=prompts[promptIndex++%prompts.length];if(!$('#note').value){$('#note').value=t;$('#note').dispatchEvent(new Event('input'))}else{toast(t)}$('#note').focus()});
const kindLines=['今天已经很努力了。在这里，可以先做回自己。','不必每一天都闪闪发光。普通的一天，也属于你。','你可以慢慢来，想说的话，我听着。','如果暂时找不到答案，先喝口水也很好。','你值得被认真对待，包括你自己。'];let kindIndex=0;
$('#kindBtn').addEventListener('click',()=>{showCompanion(selectedMood||'calm');$('#kindWords').textContent=mood(selectedMood||'calm').words});
const hugs=['抱抱已经送达 ♡','心事先放这里，我陪你一会儿。','今天辛苦啦，靠一下也可以。','不用说完整，我也愿意听。'];let hugIndex=0;
$('#hugBtn').addEventListener('click',()=>{const b=$('#mascotBubble');b.textContent=hugs[hugIndex++%hugs.length];b.classList.add('show');clearTimeout(bubbleTimer);bubbleTimer=setTimeout(()=>b.classList.remove('show'),3200);$('#hugBtn').classList.remove('bounce');void $('#hugBtn').offsetWidth;$('#hugBtn').classList.add('bounce')});
function resetForm(){editing=null;selectMood('');selectedTags.clear();syncTags();$('#note').value='';$('#wordCount').textContent='0 / 1500';$('#intensity').value=3;$('#intensityValue').textContent='3 / 5';$('#editorTitle').textContent='给此刻的自己，留一句话';$('#saveBtn').textContent='收好这一刻 ↗';$('#cancelEdit').hidden=true}
$('#entryForm').addEventListener('submit',e=>{e.preventDefault();if(!selectedMood){toast('先选一个接近此刻的心情吧。');$('.mood').focus();return}const current=activeRecords(),old=current.find(r=>r.id===editing);const now=new Date().toISOString();const r={id:old?.id||(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(16).slice(2)),created:old?.created||now,updated:now,mood:selectedMood,intensity:Number($('#intensity').value),note:$('#note').value.trim(),tags:[...selectedTags]};const next=old?current.map(x=>x.id===old.id?r:x):[r,...current];if(!persist(next))return;const wasEditing=Boolean(old);resetForm();render();toast(wasEditing?'这段心情已经更新。':'收好啦，每一种心情都值得被看见 ♡');$('#hugBtn').click()});
$('#cancelEdit').addEventListener('click',resetForm);
function view(id){if(!['today','memories','rest'].includes(id))id='today';$$('.view').forEach(e=>e.hidden=e.id!==id);$$('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===id);if(b.dataset.view===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(id!=='rest')stopRest();if(id==='memories')renderCalendar();window.scrollTo({top:0,behavior:'instant'})}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.view;view(b.dataset.view)}));window.addEventListener('hashchange',()=>view(location.hash.slice(1)));
function sorted(){return [...activeRecords()].sort((a,b)=>Date.parse(b.created)-Date.parse(a.created))}
function empty(text){const e=make('div','empty');e.append(make('span','','✧'),make('div','',text));return e}
function renderRecent(){const root=$('#recentList');root.replaceChildren();const list=sorted().slice(0,3);if(!list.length){root.append(empty('还没有写下的片段\n从今天的一句心情开始吧'));return}list.forEach(r=>{const b=make('button','recent-item');b.append(face(mood(r.mood)));const d=make('div');d.append(make('p','',r.note||`此刻，我感到${mood(r.mood).label}`),make('small','',new Date(r.created).toLocaleDateString('zh-CN',{month:'long',day:'numeric'})+' · '+mood(r.mood).label));b.append(d);b.addEventListener('click',()=>{selectedDay=dateKey(new Date(r.created));$('#search').value='';$('#filterMood').value='';location.hash='memories';view('memories');renderEntries()});root.append(b)})}
function renderCalendar(){const y=month.getFullYear(),m=month.getMonth();$('#monthTitle').textContent=`${y} 年 ${m+1} 月`;const root=$('#calendarGrid');root.replaceChildren();const offset=(new Date(y,m,1).getDay()+6)%7;for(let i=0;i<offset;i++)root.append(make('span'));for(let d=1;d<=new Date(y,m+1,0).getDate();d++){const day=dateKey(new Date(y,m,d));const b=make('button','day',String(d));b.classList.toggle('today',day===dateKey(new Date()));b.classList.toggle('chosen',day===selectedDay);const rs=activeRecords().filter(r=>dateKey(new Date(r.created))===day);b.setAttribute('aria-label',`${m+1}月${d}日，${rs.length}条记录`);b.setAttribute('aria-pressed',String(day===selectedDay));if(rs.length){const dots=make('div','dots');[...new Set(rs.map(r=>r.mood))].slice(0,3).forEach(id=>{const dot=make('i');dot.style.setProperty('--dot',mood(id).color);dots.append(dot)});b.append(dots)}b.addEventListener('click',()=>{selectedDay=selectedDay===day?'':day;renderCalendar();renderEntries()});root.append(b)}}
$('#prevMonth').addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);renderCalendar()});$('#nextMonth').addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);renderCalendar()});$('#allEntries').addEventListener('click',()=>{selectedDay='';renderCalendar();renderEntries()});
function renderEntries(){const search=$('#search').value.trim().toLowerCase(),filter=$('#filterMood').value;const list=sorted().filter(r=>(!selectedDay||dateKey(new Date(r.created))===selectedDay)&&(!filter||r.mood===filter)&&(!search||(r.note+' '+r.tags.join(' ')).toLowerCase().includes(search)));$('#entriesTitle').textContent=selectedDay?selectedDay+' 的心情':'我的心情手记';$('#entryTotal').textContent=`${list.length} 条`;const root=$('#entriesList');root.replaceChildren();if(!list.length)root.append(empty(selectedDay?'这一天还没有符合条件的记录。':'这里还没有符合条件的小片段。'));list.forEach(r=>{const e=make('article','entry'),head=make('div','entry-head'),info=make('div');info.append(make('span','',`${mood(r.mood).label} · 感受强度 ${r.intensity}/5`),make('small','',new Date(r.created).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'})));head.append(face(mood(r.mood)),info);e.append(head,make('p','',r.note||'只记录了心情，也很好。'),make('div','entry-tags',r.tags.map(t=>'#'+t).join('  ')));const actions=make('div','entry-actions'),edit=make('button','text-button','编辑'),del=make('button','text-button','删除');edit.addEventListener('click',()=>{editing=r.id;selectMood(r.mood);selectedTags=new Set(r.tags);syncTags();$('#note').value=r.note;$('#note').dispatchEvent(new Event('input'));$('#intensity').value=r.intensity;$('#intensity').dispatchEvent(new Event('input'));$('#editorTitle').textContent='再听听，当时的自己';$('#saveBtn').textContent='保存修改 ↗';$('#cancelEdit').hidden=false;location.hash='today';view('today');$('#note').focus()});del.addEventListener('click',()=>{pendingDelete=r.id;$('#deleteDialog').showModal()});actions.append(edit,del);e.append(actions);root.append(e)})}
$('#search').addEventListener('input',renderEntries);$('#filterMood').addEventListener('change',renderEntries);
$('#confirmDelete').addEventListener('click',()=>{if(persist(activeRecords().filter(r=>r.id!==pendingDelete))){if(editing===pendingDelete)resetForm();$('#deleteDialog').close();render();toast('这段记录已删除。')}pendingDelete=null});
$('#exportBtn').addEventListener('click',()=>{if(!activeRecords().length){toast('还没有可导出的记录。');return}const blob=new Blob([JSON.stringify({app:'奶娃的小晴岛',exported:new Date().toISOString(),demo,records:sorted()},null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=make('a');a.href=url;a.download=`奶娃心情手记-${demo?'演示-':''}${dateKey(new Date())}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('导出已开始，请妥善保存文件。')});
function render(){renderRecent();renderCalendar();renderEntries()}
function seedDemo(){const samples=[['calm','今天终于把困住我的报错解决了。原来问一句“可以帮我看看吗”，没有想象中那么难。',['学业'],0],['tired','任务有一点多，今晚想早点休息。先照顾好自己，再慢慢来。',['生活'],1],['happy','和朋友散步时，看到了一朵很好看的云。平凡的小事也让人开心。',['人际'],3],['anxious','想到比赛还是有点紧张。先把我负责的那一页整理好。',['竞赛'],5]];return samples.map((s,i)=>{const d=new Date();d.setDate(d.getDate()-s[3]);return {id:'demo-'+i,created:d.toISOString(),updated:d.toISOString(),mood:s[0],note:s[1],tags:s[2],intensity:3}})}
function setDemo(on){if($('#note').value&&!confirm('切换模式会清空当前未保存的文字，要继续吗？'))return;demo=on;document.body.classList.toggle('demo-mode',on);if(on)demoRecords=seedDemo();resetForm();selectedDay='';$('#search').value='';$('#filterMood').value='';month=new Date(new Date().getFullYear(),new Date().getMonth(),1);$('#demoBanner').hidden=!on;$('#demoBtn').textContent=on?'退出演示':'班会演示';$('#saveBtn').disabled=!on&&!storageAvailable;render();toast(on?'已进入演示模式，只使用虚构的示例记录。':'已回到你自己的手记。')}
$('#demoBtn').addEventListener('click',()=>setDemo(!demo));$('#exitDemo').addEventListener('click',()=>setDemo(false));
function stopRest(completed=false){if(restTimer)clearInterval(restTimer);restTimer=null;$('#orb').classList.remove('running');$('#breathBtn').textContent='开始陪伴';$('#breathText').textContent=completed?'谢谢自己':'慢慢来';$('#timerText').textContent=completed?'这一分钟，属于你':'给自己一分钟';$('#breathHelp').textContent='双脚轻轻踩地，松松肩膀。按自己的节奏舒适呼吸，无需跟随圆圈。'}
$('#breathBtn').addEventListener('click',()=>{if(restTimer){stopRest();return}restEnd=Date.now()+60000;$('#breathBtn').textContent='结束这一小会儿';$('#orb').classList.add('running');const tick=()=>{const left=Math.max(0,Math.ceil((restEnd-Date.now())/1000));$('#timerText').textContent=`还剩 ${left} 秒`;$('#breathText').textContent=left>40?'松松肩膀':left>20?'看看周围':'静静待着';if(left<=0){stopRest(true);toast('这一分钟已经收好，按自己的节奏继续吧。')}};tick();restTimer=setInterval(tick,250)});
