const plays=[[26,'单手撑住！烦恼先歇一歇。'],[44,'顶橘子举石头，今天的平衡大师就是我。'],[4,'把自己团成一颗快乐丸子。'],[22,'伸个懒腰，肩膀也放个假。'],[18,'小风扇就位，吹走一点闷闷的心情。'],[23,'偷偷调皮一下。'],[33,'叉腰站好，我是你的队友。'],[34,'小步出发，不必跑得很快。'],[36,'给今天的一小步欢呼。'],[32,'双倍的耶，送给你！'],[21,'收到！奶娃已就位。'],[29,'补充能量也是正经事。'],[31,'休息时间，想喝点什么？'],[35,'给你一个小小的啵。'],[5,'今天允许自己圆滚滚地发呆。'],[16,'有奶娃在，先给自己一点底气。'],[37,'镜头看这里，留下一个小笑容。'],[40,'眨眨眼，我们慢慢来。']];
$('#playBtn').addEventListener('click',()=>{const [n,t]=plays[playIndex++%plays.length];setScene($('#playMascot'),n,t);$('#playLine').textContent='“'+t+'”'});
$('#releaseBtn').addEventListener('click',()=>{const input=$('#worry');if(!input.value.trim()){toast('可以先写一个想暂时放下的词。');input.focus();return}input.classList.add('floating-away');$('#releaseBtn').disabled=true;setTimeout(()=>{input.value='';input.classList.remove('floating-away');$('#releaseBtn').disabled=false;$('#releaseMessage').textContent='这句话没有被保存。先给自己一点空隙。';$('#playBtn').click()},1000)});
$$('.privacy-open').forEach(b=>b.addEventListener('click',()=>$('#privacyDialog').showModal()));$$('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).close()));
window.addEventListener('beforeunload',e=>{if($('#note').value){e.preventDefault();e.returnValue=''}});
window.addEventListener('storage',e=>{if(e.key===KEY&&!demo){try{const next=JSON.parse(e.newValue||'[]');if(Array.isArray(next)&&next.every(validateRecord)){records=next;render()}}catch{}}});
const companionSets={happy:[36,37,25,17],calm:[30,42,24,17],sad:[1,2,15,43],anxious:[43,41,27],angry:[28,2,27],tired:[19,20,47,9]};
const sceneCounters={};
function setScene(img,n,alt){img.src='assets/scene-'+n+'.jpg';img.alt=alt;}
