const quietScenes=[[7,'一起看海，让思绪慢一点。'],[12,'看一会儿窗外，不用急着到达。'],[48,'下雨的时候，也可以安静待着。'],[49,'城市亮着灯，今晚先照顾自己。'],[46,'坐一会儿，我陪着你。'],[47,'靠一靠，允许自己休息。'],[11,'看看远处的灯光。'],[8,'今天走过的路，都算数。'],[6,'和自己打个招呼：辛苦啦。'],[10,'好好吃一顿，照顾此刻的自己。'],[13,'睡前给手机放个假，也给自己一点安静。'],[14,'抬头看看灯光，感受自己正待在这里。'],[9,'躺一会儿也没有关系。'],[20,'愿你今晚睡得安稳。'],[19,'抱紧小熊，慢慢放松。']];
